const rows = $input.all();
const mapMaquinas = {};
for (const item of rows) {
  const r = item.json;
  if (r.codigo_legacy) mapMaquinas[r.codigo_legacy] = r.id_maquina;
}
$getWorkflowStaticData('global').mapeoMaquinas = mapMaquinas;
return [{ json: { mapeos_cargados: true } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.tiemposMaquinaProcesadas) staticData.tiemposMaquinaProcesadas = [];
const ids = $input.all().map(item => String(item.json.ID_TiempoMaquina || '').trim()).filter(id => id);
staticData.tiemposMaquinaProcesadas.push(...ids);
return $input.all();

const loteItems = $input.all().map(item => item.json);
const mapMaquinas = $getWorkflowStaticData('global').mapeoMaquinas || {};

const escape = (v) => String(v).replace(/'/g, "''");

// Limitar cualquier texto a un máximo de 255 caracteres (para no exceder VARCHAR(255))
const limitar = (val, max = 255) => {
  if (val === undefined || val === null || val === '') return null;
  return String(val).slice(0, max);
};

// Función para convertir fecha/hora (dd/mm/yyyy hh:mm:ss) a timestamp SQL
const formatTimestamp = (fechaStr) => {
  if (!fechaStr) return 'NULL';
  const partes = fechaStr.split(' ');
  const fecha = partes[0];
  const hora = partes[1] || '00:00:00';
  const [d, m, a] = fecha.split('/');
  if (!d || !m || !a) return 'NULL';
  return `'${a}-${m.padStart(2, '0')}-${d.padStart(2, '0')} ${hora}'`;
};

// Nueva función para convertir solo fecha (dd/mm/yyyy) a date SQL
const formatDate = (fechaStr) => {
  if (!fechaStr) return 'NULL';
  const limpia = fechaStr.replace(/-/g, '/');
  const partes = limpia.split('/');
  if (partes.length !== 3) return 'NULL';
  const [d, m, a] = partes;
  if (!d || !m || !a) return 'NULL';
  return `'${a}-${m.padStart(2, '0')}-${d.padStart(2, '0')}'`;
};

const parseNumber = (val) => {
  if (val === undefined || val === null || val === '') return 'NULL';
  const num = parseFloat(String(val).replace(',', '.'));
  return isNaN(num) ? 'NULL' : num;
};

const values = loteItems.map(item => {
  const legacyId = item.ID_TiempoMaquina ? `'${escape(item.ID_TiempoMaquina)}'` : 'NULL';
  const origenId = item.IDOrigen_TiempoMaquina ? `'${escape(item.IDOrigen_TiempoMaquina)}'` : 'NULL';
  const progLegacyId = item.IDProgramacion_TiempoMaquina ? `'${escape(item.IDProgramacion_TiempoMaquina)}'` : 'NULL';
  const idMaquina = mapMaquinas[item.Maquina_TiempoMaquina] ?? 'NULL';

  // Aplicar limitar a los campos de texto que podrían superar 255
  const tipo = limitar(item.Tipo_TiempoMaquina) ? `'${escape(limitar(item.Tipo_TiempoMaquina))}'` : 'NULL';
  const proceso = limitar(item.Proceso_TiempoMaquina) ? `'${escape(limitar(item.Proceso_TiempoMaquina))}'` : 'NULL';
  const rollo = limitar(item.Rollo_TiempoMaquina) ? `'${escape(limitar(item.Rollo_TiempoMaquina))}'` : 'NULL';
  const contadorRollo = parseInt(item.ContadorRollo_TiempoMaquina) || 0;
  const turno = limitar(item.Turno_TiempoMaquina) ? `'${escape(limitar(item.Turno_TiempoMaquina))}'` : 'NULL';

  const inicio = formatTimestamp(item.Inicio_TiempoMaquina);
  const fin = formatTimestamp(item.Fin_TiempoMaquina);

  let duracion = parseFloat(item.Duracion_TiempoMaquina);
  if (isNaN(duracion) || duracion < 0) duracion = 0;

  const kilos = parseNumber(item.CantidadKilos_TiempoMaquina);
  const productividad = parseNumber(item.Productividad_TiempoMaquina);
  const retail = parseNumber(item.Retail_TiempoMaquina);

  // Solución: truncar motivo_retail a 255 caracteres
  const motivoRaw = limitar(item.MotivoRetail_TiempoMaquina, 255);
  const motivoRetail = motivoRaw ? `'${escape(motivoRaw)}'` : 'NULL';

  // NUEVO: fecha de producción
  const fechaProduccion = item.FechaProduccion_TeimposMaquina
    ? formatDate(item.FechaProduccion_TeimposMaquina)
    : 'NULL';

  return `(${legacyId}, ${origenId}, ${progLegacyId}, NULL, ${idMaquina}, ${tipo}, ${proceso}, ${rollo}, ${contadorRollo}, ${turno}, ${inicio}, ${fin}, ${duracion}, ${kilos}, ${productividad}, ${retail}, ${motivoRetail}, ${fechaProduccion})`;
}).join(', ');

if (!values) {
  return [{ json: { sql: '', status: 'sin_datos' } }];
}

const sql = `INSERT INTO public.tiempos_maquina 
  (legacy_id, legacy_origen_id, legacy_programacion_id, id_programacion, id_maquina, tipo, proceso, rollo, contador_rollo, turno, fecha_inicio, fecha_fin, duracion_horas, cantidad_kilos, productividad, retail_kilos, motivo_retail, fecha_produccion)
VALUES ${values}
ON CONFLICT (legacy_id) DO UPDATE SET
  legacy_origen_id = EXCLUDED.legacy_origen_id,
  legacy_programacion_id = EXCLUDED.legacy_programacion_id,
  id_maquina = EXCLUDED.id_maquina,
  tipo = EXCLUDED.tipo,
  proceso = EXCLUDED.proceso,
  rollo = EXCLUDED.rollo,
  contador_rollo = EXCLUDED.contador_rollo,
  turno = EXCLUDED.turno,
  fecha_inicio = EXCLUDED.fecha_inicio,
  fecha_fin = EXCLUDED.fecha_fin,
  duracion_horas = EXCLUDED.duracion_horas,
  cantidad_kilos = EXCLUDED.cantidad_kilos,
  productividad = EXCLUDED.productividad,
  retail_kilos = EXCLUDED.retail_kilos,
  motivo_retail = EXCLUDED.motivo_retail,
  fecha_produccion = EXCLUDED.fecha_produccion;`;

return [{ json: { sql } }];

const idsProcesados = $getWorkflowStaticData('global').tiemposMaquinaProcesadas || [];
if (idsProcesados.length === 0) {
  return [{ json: { sql: null } }];
}
const lista = idsProcesados.map(id => `'${String(id).replace(/'/g, "''")}'`).join(', ');
const sql = `DELETE FROM public.tiempos_maquina WHERE legacy_id NOT IN (${lista})`;
return [{ json: { sql } }];
